class _MessagesPageState extends State<MessagesPage>{int tab=0;final search=TextEditingController();final items=const[Msg('Yeni mesaj','“Aracınızın önünde kaldım, dönüş yapabilir misiniz?”','14:32','message',true),Msg('Arama isteği','Numara gizli','12:18','call',false),Msg('Otopark çıkışı','“Teşekkür ederim, sorun çözüldü.”','Dün','parking',false),Msg('Mert Y.','“Aracınız hâlâ müsait mi?”','Dün','message',true),Msg('Zeynep K.','“Çok teşekkürler, iyi akşamlar.”','2 gün önce','message',false)];@override void initState(){super.initState();search.addListener(_refresh);}@override void dispose(){search.removeListener(_refresh);search.dispose();super.dispose();}void _refresh()=>setState((){});void _open(Msg m){Navigator.push(context,MaterialPageRoute(builder:(_)=>m.type=='call'?const CallPage():MessageDetailPage(message:m)));}@override Widget build(BuildContext context){final filtered=items.where((m){if(tab==1&&!m.unread)return false;if(tab==2&&m.type!='call')return false;if(tab==3&&m.type!='parking')return false;final q=search.text.trim().toLowerCase();return q.isEmpty||'${m.title} ${m.body}'.toLowerCase().contains(q);}).toList();return page((s)=>[header(s),SizedBox(height:24*s),Text('Mesajlar',style:TextStyle(fontSize:31*s,fontWeight:FontWeight.w900)),SizedBox(height:7*s),Text('Aracınızla ilgili tüm mesajlar burada.',style:TextStyle(fontSize:14.5*s,color:C.muted)),SizedBox(height:18*s),TextField(controller:search,decoration:InputDecoration(prefixIcon:const Icon(Icons.search_rounded),hintText:'Mesajlarda ara...',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:BorderSide.none))),SizedBox(height:14*s),SizedBox(height:47*s,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:4,separatorBuilder:(_,__)=>SizedBox(width:8*s),itemBuilder:(_,i){final labels=['Tümü','Yeni','Arama İstekleri','Otopark'];final active=tab==i;return InkWell(onTap:()=>setState(()=>tab=i),borderRadius:BorderRadius.circular(17*s),child:Container(padding:EdgeInsets.symmetric(horizontal:13*s),alignment:Alignment.center,decoration:BoxDecoration(color:active?const Color(0xFFFFF7EB):Colors.white,borderRadius:BorderRadius.circular(17*s),border:Border.all(color:active?const Color(0xFFFFC874):C.line)),child:Text(labels[i],style:TextStyle(color:active?C.orange:C.muted,fontWeight:FontWeight.w700))));})),SizedBox(height:16*s),...filtered.map((m)=>Padding(padding:EdgeInsets.only(bottom:9*s),child:Material(color:Colors.white,borderRadius:BorderRadius.circular(20*s),child:InkWell(onTap:()=>_open(m),borderRadius:BorderRadius.circular(20*s),child:Padding(padding:EdgeInsets.all(14*s),child:Row(children:[CircleAvatar(backgroundColor:const Color(0xFFFFF1E4),child:Icon(m.type=='call'?Icons.phone_rounded:m.type=='parking'?Icons.local_parking_rounded:Icons.person_rounded,color:C.orange)),SizedBox(width:12*s),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(m.title,style:TextStyle(fontSize:15*s,fontWeight:FontWeight.w900)),Text(m.body,maxLines:2,overflow:TextOverflow.ellipsis,style:TextStyle(fontSize:12.5*s,color:C.muted))])),Text(m.time,style:TextStyle(fontSize:11.5*s,color:C.muted)),Icon(Icons.chevron_right_rounded,size:20*s,color:C.muted)]))))))]);}}
